shell:
PLUGIN="$TMPDIR/pg-eval-2Rtadv/.cursor"
WS="$TMPDIR/pg-eval-2Rtadv"
cp "$PLUGIN/assets/tracker.csv" "$WS/upgrade/tracker.csv"
node <<'NODE'
const fs = require('fs');
const path = '$TMPDIR/pg-eval-2Rtadv/upgrade/tracker.csv';
let text = fs.readFileSync(path, 'utf8');
const lines = text.trimEnd().split('\n');
const header = lines[0].split(',');
const idx = (name) => header.indexOf(name);
const today = '2026-11-04';

function parseLine(line) {
  const cols = [];
  let cur = '';
  let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') { inQ = !inQ; cur += c; continue; }
    if (c === ',' && !inQ) { cols.push(cur); cur = ''; continue; }
    cur += c;
  }
  cols.push(cur);
  return cols;
}

function serialize(cols) {
  return cols.map((c) => (c.includes(',') || c.includes('"') ? c : c)).join(',');
}

const out = [lines[0]];
for (let li = 1; li < lines.length; li++) {
  const cols = parseLine(lines[li]);
  const id = cols[idx('ID')];
  const ownerRole = cols[idx('Owner role')];

  if (ownerRole === 'Program owner') {
    cols[idx('Owner')] = 'Jo Park';
  }

  if (id === 'B0-01') {
    cols[idx('Status')] = 'Done';
    cols[idx('Evidence')] = 'upgrade/results/code-search-northwind-labs.txt';
    cols[idx('Last checked')] = today;
    cols[idx('Status since')] = today;
    cols[idx('Notes')] = 'No public repos in org; zero code hits.';
  }

  if (id === 'Q-07') {
    cols[idx('Status')] = 'Waiting on customer';
    cols[idx('Owner')] = 'Jo Park';
    cols[idx('Last checked')] = today;
    cols[idx('Status since')] = today;
    cols[idx('Notes')] = 'GitHub code search found nothing; org reports 0 public repos. Need full repo/service list.';
  }

  if (id === 'Q-01') {
    cols[idx('Last checked')] = today;
    cols[idx('Notes')] = 'Bootstrap draft: 45 minutes on a Sunday night; not business-approved; window mode unknown.';
  }

  if (id === 'Q-10') {
    cols[idx('Last checked')] = today;
    cols[idx('Notes')] = 'Bootstrap draft: Sunday night; specific weekend date and blackout dates still unknown.';
  }

  out.push(cols.join(','));
}

const q20 = [
  'Q-20','Question','0','Discovery','Who is the named DBA for precheck cutover and provider work?','Named person on DBA-owned tracker rows','Program owner','Jo Park','Customer','Human','','','','G0.2 G0.6','Not started','','','',today,'','','','','','','',today
].join(',');

const q21 = [
  'Q-21','Question','0','Discovery','During the window must read traffic stop or may reads continue?','read-write vs write-only recorded in decision record','Program owner','Jo Park','Customer','Human','','','','G0.6','Not started','','','',today,'','','','','','','',today
].join(',');

out.push(q20, q21);
fs.writeFileSync(path, out.join('\n') + '\n');
NODE
node "$PLUGIN/scripts/tracker-check.mjs" "$WS/upgrade/tracker.csv"
